    const params=new URLSearchParams();if(query)params.set('q',query);if(kind!=='All')params.set('kind',kind);
    if(completeOnly)params.set('coverage','complete');
    if(comparisonLane!=='All comparisons')params.set('lane',comparisonLane);
    history.replaceState(null,'','/'+(params.size?'?'+params:'')+(location.hash||''));
